function drawPhotoCover(ctx,img,x,y,w,h){const scale=Math.max(w/img.width,h/img.height),sw=w/scale,sh=h/scale;ctx.drawImage(img,(img.width-sw)/2,(img.height-sh)/2,sw,sh,x,y,w,h)}let routeReady=Promise.resolve();const recapPin=new Image();recapPin.src='assets/route_leading_yellow.svg';function route(){const r=$('route').getContext('2d'),layout=RECORD_LAYOUT,projectRecord=createRecordProjection(track);r.clearRect(0,0,layout.width,layout.height);if(track.length<2)return routeReady=Promise.resolve();r.beginPath();track.forEach((p,i)=>{let q=projectRecord(p);i?r.lineTo(q.x,q.y):r.moveTo(q.x,q.y)});r.strokeStyle=recordColor;r.lineWidth=5;r.lineJoin='round';r.lineCap='round';r.stroke();routeReady=Promise.all(photos.map(async p=>{const img=new Image();img.src=p.src;await img.decode();return{p,img}})).then(async loaded=>{for(const {p,img} of loaded){const q=projectRecord(p);r.save();r.beginPath();r.roundRect(q.x-22,q.y-26,44,52,10);r.clip();drawPhotoCover(r,img,q.x-22,q.y-26,44,52);r.restore();r.strokeStyle=recordColor;r.lineWidth=4;r.beginPath();r.roundRect(q.x-22,q.y-26,44,52,10);r.stroke()}});return routeReady}
